const rows = $input.all().map(item => item.json);

const totalCustomers = rows.length;
const churned = rows.filter(r =>
  String(r.Churn ?? '').trim().toLowerCase() === 'yes'
);
const retained = rows.filter(r =>
  String(r.Churn ?? '').trim().toLowerCase() === 'no'
);

const percent = (n, total) =>
  total ? Number((n / total * 100).toFixed(2)) : 0;

function average(records, field) {
  const values = records
    .map(r => Number(r[field]))
    .filter(v => Number.isFinite(v));

  return values.length
    ? Number((values.reduce((sum, v) => sum + v, 0) / values.length).toFixed(2))
    : null;
}

function groupByChurn(field) {
  const groups = {};

  for (const row of rows) {
    const key = String(row[field] ?? 'Unknown').trim() || 'Unknown';

    if (!groups[key]) {
      groups[key] = { customers: 0, churned: 0 };
    }

    groups[key].customers++;

    if (String(row.Churn ?? '').trim().toLowerCase() === 'yes') {
      groups[key].churned++;
    }
  }

  return Object.entries(groups).map(([group, data]) => ({
    group,
    customers: data.customers,
    churned: data.churned,
    churnRatePct: percent(data.churned, data.customers)
  }));
}

const invalidChurn = rows.filter(r =>
  !['yes', 'no'].includes(
    String(r.Churn ?? '').trim().toLowerCase()
  )
).length;

return [{
  json: {
    totalCustomers,
    churnedCustomers: churned.length,
    retainedCustomers: retained.length,
    churnRatePct: percent(churned.length, totalCustomers),
    averageTenureMonths: average(rows, 'tenure'),
    averageMonthlyCharges: average(rows, 'MonthlyCharges'),
    averageTotalCharges: average(rows, 'TotalCharges'),
    churnByContract: groupByChurn('Contract'),
    churnByInternetService: groupByChurn('InternetService'),
    dataQuality: {
      missingCustomerIDs: rows.filter(r =>
        !String(r.customerID ?? '').trim()
      ).length,
      invalidChurnValues: invalidChurn,
      missingTotalCharges: rows.filter(r =>
        String(r.TotalCharges ?? '').trim() === ''
      ).length
    }
  }
}];
